// Enhanced validation and API connectivity testing
const config = $input.first().json;

// Validation functions
const validateUrl = (url) => {
  if (!url || typeof url !== 'string') return false;
  try {
    const urlObj = new URL(url);
    return urlObj.protocol === 'http:' || urlObj.protocol === 'https:';
  } catch {
    return false;
  }
};

const validateApiKey = (key) => {
  if (!key || typeof key !== 'string') return false;
  return key.length > 10 && 
         !key.includes('your_') && 
         !key.includes('YOUR_') && 
         !key.includes('{{') && 
         !key.includes('undefined') &&
         key.trim() !== '';
};

const validateConfig = (configObj, configName) => {
  const errors = [];
  const warnings = [];

  if (!configObj) {
    errors.push(`${configName} configuration is missing`);
    return { errors, warnings };
  }

  switch (configName) {
    case 'youtube_config':
      if (!validateApiKey(configObj.access_token)) {
        errors.push('Invalid or missing YouTube access token');
      }
      if (!configObj.client_id || !configObj.client_secret) {
        errors.push('Missing YouTube OAuth credentials (client_id/client_secret)');
      }
      if (!configObj.channel_id) {
        warnings.push('YouTube channel ID not configured');
      }
      if (!configObj.default_category || !configObj.default_privacy) {
        warnings.push('YouTube default upload settings not configured');
      }
      break;

    case 'ai_services_config':
      if (!validateApiKey(configObj.google?.api_key)) {
        warnings.push('Google API key not configured');
      }
      if (!validateApiKey(configObj.elevenlabs?.api_key)) {
        warnings.push('ElevenLabs API key not configured');
      }
      if (!validateApiKey(configObj.huggingface?.token)) {
        warnings.push('Hugging Face token not configured');
      }
      if (!validateApiKey(configObj.json2video?.api_key)) {
        warnings.push('JSON2Video API key not configured');
      }
      break;

    case 'media_services_config':
      if (!validateApiKey(configObj.pixabay?.api_key)) {
        warnings.push('Pixabay API key not configured');
      }
      if (!validateApiKey(configObj.pexels?.api_key)) {
        warnings.push('Pexels API key not configured');
      }
      if (!validateApiKey(configObj.bitly?.access_token)) {
        warnings.push('Bitly access token not configured');
      }
      break;

    case 'notifications_config':
      if (!validateUrl(configObj.discord?.webhook_url)) {
        warnings.push('Discord webhook URL not configured or invalid');
      }
      if (!configObj.telegram?.bot_token || !configObj.telegram?.chat_id) {
        warnings.push('Telegram configuration incomplete (missing bot_token or chat_id)');
      }
      if (!configObj.reddit?.client_id || !configObj.reddit?.client_secret) {
        warnings.push('Reddit API credentials not configured');
      }
      break;

    case 'gcp_config':
      if (!configObj.project_id) {
        errors.push('GCP Project ID is required');
      }
      if (!configObj.service_account_key && !process.env.GOOGLE_APPLICATION_CREDENTIALS) {
        errors.push('GCP Service Account Key or GOOGLE_APPLICATION_CREDENTIALS is required');
      }
      if (!configObj.region || !configObj.zone) {
        warnings.push('GCP region/zone not configured, using defaults');
      }
      break;

    case 'system_config':
      if (!configObj.n8n?.encryption_key) {
        errors.push('N8N encryption key is required');
      }
      if (!configObj.database?.type) {
        warnings.push('Database type not specified, using default');
      }
      break;
  }

  return { errors, warnings };
};

// Validate all configurations
const validationResults = {
  youtube: validateConfig(config.youtube_config, 'youtube_config'),
  ai_services: validateConfig(config.ai_services_config, 'ai_services_config'),
  media_services: validateConfig(config.media_services_config, 'media_services_config'),
  notifications: validateConfig(config.notifications_config, 'notifications_config'),
  gcp: validateConfig(config.gcp_config, 'gcp_config'),
  system: validateConfig(config.system_config, 'system_config')
};

// Collect all errors and warnings
const allErrors = [];
const allWarnings = [];

Object.entries(validationResults).forEach(([service, result]) => {
  allErrors.push(...result.errors.map(error => `${service}: ${error}`));
  allWarnings.push(...result.warnings.map(warning => `${service}: ${warning}`));
});

// Determine configuration status
let status = 'healthy';
let statusMessage = 'All configurations are valid';

if (allErrors.length > 0) {
  status = 'error';
  statusMessage = `Configuration errors detected: ${allErrors.join(', ')}`;
} else if (allWarnings.length > 0) {
  status = 'warning';
  statusMessage = `Configuration warnings: ${allWarnings.join(', ')}`;
}

// Create service status summary
const serviceStatus = {
  youtube: {
    enabled: validateApiKey(config.youtube_config?.access_token) && config.youtube_config?.client_id,
    oauth_configured: !!(config.youtube_config?.client_id && config.youtube_config?.client_secret),
    channel_linked: !!config.youtube_config?.channel_id,
    upload_defaults_set: !!(config.youtube_config?.default_category && config.youtube_config?.default_privacy)
  },
  ai_services: {
    google: validateApiKey(config.ai_services_config?.google?.api_key),
    elevenlabs: validateApiKey(config.ai_services_config?.elevenlabs?.api_key),
    huggingface: validateApiKey(config.ai_services_config?.huggingface?.token),
    json2video: validateApiKey(config.ai_services_config?.json2video?.api_key)
  },
  media_services: {
    pixabay: validateApiKey(config.media_services_config?.pixabay?.api_key),
    pexels: validateApiKey(config.media_services_config?.pexels?.api_key),
    bitly: validateApiKey(config.media_services_config?.bitly?.access_token)
  },
  notifications: {
    discord: validateUrl(config.notifications_config?.discord?.webhook_url),
    telegram: !!(config.notifications_config?.telegram?.bot_token && config.notifications_config?.telegram?.chat_id),
    reddit: !!(config.notifications_config?.reddit?.client_id && config.notifications_config?.reddit?.client_secret)
  },
  gcp: {
    project_configured: !!config.gcp_config?.project_id,
    service_account_configured: !!(config.gcp_config?.service_account_key || process.env.GOOGLE_APPLICATION_CREDENTIALS),
    secret_manager_enabled: config.gcp_config?.secret_manager?.enabled === true,
    cloud_functions_configured: !!(config.gcp_config?.cloud_functions?.token_refresh_url && config.gcp_config?.cloud_functions?.notification_url)
  },
  system: {
    encryption_configured: !!config.system_config?.n8n?.encryption_key,
    database_configured: !!config.system_config?.database?.type,
    monitoring_enabled: !!config.system_config?.monitoring,
    timezone_set: !!config.system_config?.n8n?.timezone
  }
};

// Calculate overall health score
const totalChecks = Object.values(serviceStatus).reduce((total, service) => {
  return total + Object.keys(service).length;
}, 0);

const passedChecks = Object.values(serviceStatus).reduce((total, service) => {
  return total + Object.values(service).filter(Boolean).length;
}, 0);

const healthScore = totalChecks > 0 ? Math.round((passedChecks / totalChecks) * 100) : 0;

// Add connectivity test flags
const connectivityTests = {
  youtube_api_test: false,
  google_cloud_test: false,
  discord_webhook_test: false,
  telegram_bot_test: false
};

return {
  json: {
    // Configuration data
    ...config,

    // Validation results
    validation: {
      status: status,
      message: statusMessage,
      errors: allErrors,
      warnings: allWarnings,
      health_score: healthScore
    },

    // Service status
    service_status: serviceStatus,

    // Connectivity test results (to be populated by subsequent nodes)
    connectivity_tests: connectivityTests,

    // Metadata
    config_version: '2.0.0',
    validated_at: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'production'
  }
};

// Get fresh YouTube access token using refresh token
const config = $input.first().json;

if (!config.youtube_config.refresh_token) {
  return {
    json: {
      ...config,
      youtube_token_error: 'No refresh token available'
    }
  };
}

const tokenRequest = {
  client_id: config.youtube_config.client_id,
  client_secret: config.youtube_config.client_secret,
  refresh_token: config.youtube_config.refresh_token,
  grant_type: 'refresh_token'
};

return {
  json: {
    ...config,
    token_request: tokenRequest
  }
};

