// Enhanced connectivity test results processing
const configData = $input.first().json;
const allInputs = $input.all();

// Helper function to safely check response status
const checkResponseStatus = (response) => {
  if (!response) return false;

  // Check if it's a successful HTTP response
  if (response.statusCode && response.statusCode >= 200 && response.statusCode < 300) {
    return true;
  }

  // Check if there's valid JSON data without errors
  if (response.json && !response.error) {
    return true;
  }

  // Check for specific success indicators
  if (response.json) {
    // YouTube API success indicators
    if (response.json.items || response.json.kind === 'youtube#channelListResponse') {
      return true;
    }

    // Google Cloud API success indicators
    if (response.json.projectId || response.json.name || response.json.projectNumber) {
      return true;
    }

    // Telegram API success indicators
    if (response.json.ok === true || response.json.result) {
      return true;
    }

    // OAuth token response success indicators
    if (response.json.access_token && response.json.token_type) {
      return true;
    }
  }

  return false;
};

// Process each connectivity test
const youtubeTokenTest = allInputs.find(item => {
  const url = item.json?.url || '';
  return url.includes('oauth2.googleapis.com/token');
});

const youtubeApiTest = allInputs.find(item => {
  const url = item.json?.url || '';
  return url.includes('youtube') || url.includes('googleapis.com/youtube');
});

const gcpTest = allInputs.find(item => {
  const url = item.json?.url || '';
  return url.includes('cloudresourcemanager') || url.includes('googleapis.com/v1/projects');
});

const discordTest = allInputs.find(item => {
  const url = item.json?.url || '';
  return url.includes('discord.com/api/webhooks');
});

const telegramTest = allInputs.find(item => {
  const url = item.json?.url || '';
  return url.includes('api.telegram.org');
});

// Check YouTube token refresh and API access
let youtubeTestResult = false;
if (youtubeTokenTest && checkResponseStatus(youtubeTokenTest)) {
  // Token refresh successful, check API access
  youtubeTestResult = youtubeApiTest ? checkResponseStatus(youtubeApiTest) : false;
} else {
  // Token refresh failed
  youtubeTestResult = false;
}

// Evaluate connectivity test results
const connectivityResults = {
  youtube_api_test: youtubeTestResult,
  google_cloud_test: gcpTest ? checkResponseStatus(gcpTest) : false,
  discord_webhook_test: discordTest ? checkResponseStatus(discordTest) : false,
  telegram_bot_test: telegramTest ? checkResponseStatus(telegramTest) : false
};

// Add detailed error information for debugging
const testDetails = {
  youtube: {
    token_tested: !!youtubeTokenTest,
    token_status_code: youtubeTokenTest?.statusCode || 'N/A',
    token_error: youtubeTokenTest?.error?.message || 'None',
    api_tested: !!youtubeApiTest,
    api_status_code: youtubeApiTest?.statusCode || 'N/A',
    api_error: youtubeApiTest?.error?.message || 'None',
    response_type: youtubeApiTest?.json ? 'JSON' : 'Other'
  },
  gcp: {
    tested: !!gcpTest,
    status_code: gcpTest?.statusCode || 'N/A',
    error: gcpTest?.error?.message || 'None',
    response_type: gcpTest?.json ? 'JSON' : 'Other'
  },
  discord: {
    tested: !!discordTest,
    status_code: discordTest?.statusCode || 'N/A',
    error: discordTest?.error?.message || 'None',
    response_type: discordTest?.json ? 'JSON' : 'Other'
  },
  telegram: {
    tested: !!telegramTest,
    status_code: telegramTest?.statusCode || 'N/A',
    error: telegramTest?.error?.message || 'None',
    response_type: telegramTest?.json ? 'JSON' : 'Other'
  }
};

// Calculate connectivity score
const totalTests = Object.keys(connectivityResults).length;
const passedTests = Object.values(connectivityResults).filter(Boolean).length;
const connectivityScore = totalTests > 0 ? Math.round((passedTests / totalTests) * 100) : 0;

// Update overall health score considering connectivity
const originalHealthScore = configData.validation?.health_score || 0;
const combinedHealthScore = Math.round((originalHealthScore + connectivityScore) / 2);

// Update status based on connectivity results
let finalStatus = configData.validation?.status || 'unknown';
let finalMessage = configData.validation?.message || 'Configuration status unknown';

if (connectivityScore < 50) {
  finalStatus = 'error';
  finalMessage = `Critical connectivity issues detected. Only ${passedTests}/${totalTests} services are reachable.`;
} else if (connectivityScore < 80) {
  if (finalStatus === 'healthy') {
    finalStatus = 'warning';
  }
  finalMessage = `Some connectivity issues detected. ${passedTests}/${totalTests} services are reachable.`;
} else if (connectivityScore >= 80) {
  if (originalHealthScore >= 70) {
    finalStatus = 'healthy';
    finalMessage = `System is healthy. ${passedTests}/${totalTests} services are reachable.`;
  }
}

return {
  json: {
    ...configData,
    validation: {
      ...configData.validation,
      status: finalStatus,
      message: finalMessage,
      health_score: combinedHealthScore,
      connectivity_score: connectivityScore
    },
    connectivity_tests: connectivityResults,
    test_details: testDetails,
    test_summary: {
      total_tests: totalTests,
      passed_tests: passedTests,
      failed_tests: totalTests - passedTests,
      connectivity_score: connectivityScore,
      last_tested: new Date().toISOString()
    }
  }
};

